// 从 'htm/preact' 模块导入 html 方法
import { html } from 'htm/preact';
// 从 '@bpmn-io/properties-panel' 模块导入 SelectEntry 组件和 isSelectEntryEdited 方法
import { SelectEntry, isSelectEntryEdited } from '@bpmn-io/properties-panel';
// 从 'bpmn-js-properties-panel' 模块导入 useService 钩子函数
import { useService } from 'bpmn-js-properties-panel';
// 从 '@bpmn-io/properties-panel/preact/hooks' 模块导入 useEffect 和 useState 钩子
import { useEffect, useState } from '@bpmn-io/properties-panel/preact/hooks';

// 定义模块的默认导出函数
export default function(element) {
  return [
    {
      // id 属性定义为 'spell'
      id: 'spell',
      // 传递进来的元素
      element,
      // 指定组件为 Spell
      component: Spell,
      // 指定是否已编辑的判定方法
      isEdited: isSelectEntryEdited
    }
  ];
}

// 定义 Spell 组件
function Spell(props) {
  // 解构获取 props 中的 element 和 id 属性
  const { element, id } = props;
  // 使用 useService 钩子获取 BPMN 的 modeling 服务
  const modeling = useService('modeling');
  // 使用 useService 钩子获取翻译服务
  const translate = useService('translate');
  // 使用 useService 钩子获取 debounce 服务
  const debounce = useService('debounceInput');

  // 定义函数来获取 spell 值
  const getValue = () => {
    // 从 element 的业务对象中获取 spell，如果不存在则返回空字符串
    return element.businessObject.spell || '';
  };

  // 定义函数来设置 spell 值
  const setValue = value => {
    // 调用 modeling 服务更新元素的属性
    return modeling.updateProperties(element, {
      spell: value
    });
  };

  // 使用 useState 创建 spells 状态，并提供 setSpells 更新方法
  const [ spells, setSpells ] = useState([]);

  // 使用 useEffect 钩子在组件第一次渲染时执行异步请求
  useEffect(() => {
    // 定义异步函数来获取 spells 列表
    function fetchSpells() {
      fetch('http://localhost:1234/spell') // 使用 fetch 方法从本地服务器获取数据
          .then(res => res.json()) // 将响应转换为 JSON 格式
          .then(spellbook => setSpells(spellbook)) // 将返回的数据存入 spells 状态
          .catch(error => console.error(error)); // 捕获错误并打印到控制台
    }

    // 调用异步函数获取 spells 数据
    fetchSpells();
  }, [ setSpells ]); // 依赖于 setSpells，如果修改，将重新执行

  // 定义函数来生成选项列表
  const getOptions = () => {
    return [
      // 首个选项为 '<none>'，值为 undefined
      { label: '<none>', value: undefined },
      // 动态生成选项，将 spells 数组映射为 label 和 value 对象
      ...spells.map(spell => ({
        label: spell,
        value: spell
      }))
    ];
  };

  // 返回 SelectEntry 组件并设置其属性
  // 设置 SelectEntry 的 id 属性
  // 绑定 element 对象
  // 设置字段描述
  // 设置字段标签
  // 指定获取值的方法
  // 指定设置值的方法
  // 指定获取选项列表的方法
  // 指定 debounce 方法
  return html`<${SelectEntry}
    id=${ id } 
    element=${ element } 
    description=${ translate('Apply a black magic spell') } 
    label=${ translate('Spell') } 
    getValue=${ getValue } 
    setValue=${ setValue } 
    getOptions=${ getOptions } 
    debounce=${ debounce } 
  />`;
}
