// 导入自定义的属性条目。
// 当前条目为一个带有逻辑能力的文本输入，用于创建、更新和删除 "spell" 属性。
import spellProps from './parts/SpellProps';
// 导入 `is` 工具方法，用于检查元素类型。
import { is } from 'bpmn-js/lib/util/ModelUtil';
// 定义较低的优先级值，确保优先级低于基础 BPMN 属性。
const LOW_PRIORITY = 500;

/**
 * 提供一个包含 `#getGroups(element)` 方法的提供器，
 * 用于为图表元素暴露属性面板的分组功能。
 *
 * @param {PropertiesPanel} propertiesPanel 属性面板实例
 * @param {Function} translate 翻译函数
 */
export default function MagicPropertiesProvider(propertiesPanel, translate) {
  // API 接口 ////////

  /**
   * 返回为指定元素提供的分组。
   *
   * @param {DiagramElement} element 图表元素
   *
   * @return {(Object[]) => (Object[])} groups 中间件
   */
  this.getGroups = function(element) {
    /**
     * 我们返回一个中间件，用于修改现有的属性面板分组。
     *
     * @param {Object[]} groups 当前已经存在的分组
     *
     * @return {Object[]} 修改后的分组
     */
    return function(groups) {
      // 如果当前元素是一个 BPMN 的 StartEvent，则添加 "magic" 分组。
      if (is(element, 'bpmn:StartEvent')) {
        groups.push(createMagicGroup(element, translate));
      }
      return groups;
    };
  };

  // 注册逻辑 ////////

  // 注册我们自定义的 Magic 属性提供器。
  // 使用较低的优先级值确保在基础 BPMN 属性之后加载。
  propertiesPanel.registerProvider(LOW_PRIORITY, this);
}

// 指定依赖项，确保函数实例化时传入正确的参数。
MagicPropertiesProvider.$inject = [ 'propertiesPanel', 'translate' ];

/**
 * 创建自定义的 "Magic" 分组。
 *
 * @param {DiagramElement} element 图表元素
 * @param {Function} translate 翻译函数
 *
 * @return {Object} 定义的 Magic 分组对象
 */
function createMagicGroup(element, translate) {
  // 创建一个名为 "Magic properties" 的分组。
  const magicGroup = {
    id: 'magic', // 分组的唯一标识符
    label: translate('Magic properties'), // 分组显示的标签，支持翻译
    entries: spellProps(element) // 使用自定义的 "spellProps" 方法生成该分组相关的条目
  };
  return magicGroup;
}
