// 导入自定义属性提供器模块
import MagicPropertiesProvider from './MagicPropertiesProvider';

// 导出一个默认配置对象，用于依赖注入
export default {
  // 初始化时需要加载的组件，这里初始化时加载 `magicPropertiesProvider`
  __init__: [ 'magicPropertiesProvider' ],

  // 定义依赖项 `magicPropertiesProvider`，指定类型为 `type` 并指向 `MagicPropertiesProvider`
  magicPropertiesProvider: [ 'type', MagicPropertiesProvider ]
};
