// 导入 bpmn-js 默认的 CSS 样式
import 'bpmn-js/dist/assets/diagram-js.css';
// 导入 bpmn-js 的 BPMN 图样式
import 'bpmn-js/dist/assets/bpmn-js.css';
// 导入 bpmn 的字体样式
import 'bpmn-js/dist/assets/bpmn-font/css/bpmn-embedded.css';
// 导入 bpmn 属性面板相关的样式
import '@bpmn-io/properties-panel/assets/properties-panel.css';
// 导入自定义的样式文件
import './style.less';

// 引入 jQuery 库
import $ from 'jquery';

// 从 bpmn-js 库中导入建模器
import BpmnModeler from 'bpmn-js/lib/Modeler';

// 从 bpmn-js 属性面板库中导入相关模块
import {
  BpmnPropertiesPanelModule,
  BpmnPropertiesProviderModule
} from 'bpmn-js-properties-panel';

// 引入自定义属性提供模块
import magicPropertiesProviderModule from './provider/magic';

// 引入自定义的 moddle 描述符
import magicModdleDescriptor from './descriptors/magic';

// 从 min-dash 库中导入防抖函数
import {
  debounce
} from 'min-dash';

// 引用默认的 BPMN 图 XML 文件
import diagramXML from '../resources/newDiagram.bpmn';

// 引入自定义翻译模块
import customTranslate from "./customTranslate/customTranslate";

// 定义自定义翻译模块配置，用于替换 bpmn-js 默认的翻译机制
var customTranslateModule = {
  translate: [ 'value', customTranslate ]
};

// 通过 jQuery 获取 DOM 的容器元素
var container = $('#js-drop-zone');

// 初始化 bpmn-js 建模器实例，配置属性面板容器及扩展模块
var bpmnModeler = new BpmnModeler({
  container: '#js-canvas',
  propertiesPanel: {
    parent: '#js-properties-panel'
  },
  additionalModules: [
    customTranslateModule, // 自定义翻译模块
    BpmnPropertiesPanelModule, // 属性面板模块
    BpmnPropertiesProviderModule, // 属性提供模块
    magicPropertiesProviderModule // 自定义属性提供模块
  ],
  moddleExtensions: {
    magic: magicModdleDescriptor // 自定义的 moddle 扩展
  }
});

// 当页面加载完成时执行的逻辑
document.addEventListener('DOMContentLoaded', function () {
  // 模拟一个条件变量，用于控制是否需要从后端请求数据
  const shouldFetchData = true; // 模拟设定为需要从后端请求

  if (shouldFetchData) {
    // 如果需要请求后端数据，则发起 HTTP 请求
    console.log('向后台获取图表的 JSON 数据...');
    fetch('http://localhost:1234/api/diagram') // 这里需要替换为实际的后端 API 地址
        .then(response => {
          if (!response.ok) {
            // 如果返回状态不为 OK，则抛出错误
            throw new Error('请求出错，状态码: ' + response.status);
          }
          return response.text(); // 假设后端返回的是 XML 格式数据
        })
        .then(data => {
          // 成功获取数据后，加载图表数据
          console.log('已从后台加载图表数据');
          openDiagram(data);
        })
        .catch(error => {
          // 如果请求出现错误，则输出错误信息并加载默认图表
          console.error('加载后台数据失败:', error);
          console.log('加载失败，创建默认的新图表');
          createNewDiagram();
        });
  } else {
    // 如果不需要请求数据，直接创建一个新图表
    console.log('直接创建一个新图表...');
    createNewDiagram();
  }
});

// 创建一个新图表
function createNewDiagram() {
  openDiagram(diagramXML);
}

// 加载 BPMN 图数据的通用函数
async function openDiagram(xml) {
  try {
    // 加载 XML 数据
    await bpmnModeler.importXML(xml);

    // 设置 DOM 容器样式为加载成功
    container
        .removeClass('with-error')
        .addClass('with-diagram');
  } catch (err) {
    // 如果加载失败，设置 DOM 容器样式为错误状态
    container
        .removeClass('with-diagram')
        .addClass('with-error');
    container.find('.error pre').text(err.message); // 显示错误信息
    console.error(err);
  }
}

// 定义文件拖放相关处理逻辑
function registerFileDrop(container, callback) {
  // 定义文件选择事件处理
  function handleFileSelect(e) {
    e.stopPropagation();
    e.preventDefault();

    // 获取拖放的文件
    var files = e.dataTransfer.files;
    var file = files[0];
    var reader = new FileReader();

    // 读取文件内容
    reader.onload = function(e) {
      var xml = e.target.result;
      callback(xml); // 将读取的内容回调处理
    };

    reader.readAsText(file);
  }

  // 定义拖拽事件的样式处理
  function handleDragOver(e) {
    e.stopPropagation();
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy'; // 明确表示拖放行为为复制
  }

  // 将事件绑定到容器元素
  container.get(0).addEventListener('dragover', handleDragOver, false);
  container.get(0).addEventListener('drop', handleFileSelect, false);
}

// 检测浏览器是否支持文件拖放的 API，如果不支持则给出提示
if (!window.FileList || !window.FileReader) {
  window.alert(
      '看起来您使用的是不支持拖放功能的旧版浏览器。' +
      '建议使用 Chrome, Firefox 或 Internet Explorer > 10 版本浏览器。'
  );
} else {
  // 注册文件拖放事件
  registerFileDrop(container, openDiagram);
}

// 初始化文件操作按钮和事件
$(function() {
  // 为创建新图表按钮绑定事件
  $('#js-create-diagram').click(function(e) {
    e.stopPropagation();
    e.preventDefault();
    createNewDiagram();
  });

  // 获取下载按钮的 DOM 引用
  var downloadLink = $('#js-download-diagram');
  var downloadSvgLink = $('#js-download-svg');

  // 为按钮绑定交互效果，如果未激活则禁止默认行为
  $('.buttons a').click(function(e) {
    if (!$(this).is('.active')) {
      e.preventDefault();
      e.stopPropagation();
    }
  });

  // 定义文件导出的逻辑
  function setEncoded(link, name, data) {
    var encodedData = encodeURIComponent(data);
    if (data) {
      // 如果数据存在，激活下载链接并设置属性
      link.addClass('active').attr({
        'href': 'data:application/bpmn20-xml;charset=UTF-8,' + encodedData,
        'download': name
      });
    } else {
      // 如果数据不存在，移除激活状态
      link.removeClass('active');
    }
  }

  // 防抖处理文件导出函数
  var exportArtifacts = debounce(async function() {
    try {
      // 导出 SVG 格式
      const { svg } = await bpmnModeler.saveSVG();
      setEncoded(downloadSvgLink, 'diagram.svg', svg);
    } catch (err) {
      console.error('导出 SVG 失败: ', err);
      setEncoded(downloadSvgLink, 'diagram.svg', null);
    }

    try {
      // 导出 XML 格式
      const { xml } = await bpmnModeler.saveXML({ format: true });
      setEncoded(downloadLink, 'diagram.bpmn', xml);
    } catch (err) {
      console.error('导出 BPMN 失败: ', err);
      setEncoded(downloadLink, 'diagram.bpmn', null);
    }
  }, 500);

  // 当命令栈发生变化时，自动触发导出
  bpmnModeler.on('commandStack.changed', exportArtifacts);
});

setupAutoSave(bpmnModeler);
function setupAutoSave(modeler) {
  const eventBus = modeler.get('eventBus'); // 用于监听事件
  let isDirty = false; // 标记是否有未保存的更改
  let saving = false; // 标记是否正在保存

  // 监听图表发生变化的事件
  eventBus.on('commandStack.changed', () => {
    console.log('检测到图表已更改');
    isDirty = true; // 标记图表为已变化
  });

  // 自动保存函数
  async function autoSave() {
    if (!isDirty || saving) return; // 如果没有变更或正在保存，跳过
    saving = true; // 设置为保存中

    try {
      // 导出为 XML
      const result = await modeler.saveXML({ format: true });
      const { xml } = result;

      console.log('正在自动保存 BPMN 数据...');

      // 发送到后端保存
      const response = await fetch('http://localhost:1234/save-bpmn', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ bpmnData: xml }),
      });

      if (!response.ok) {
        throw new Error(`自动保存失败: ${response.status}`);
      }

      console.log('自动保存成功!');
      isDirty = false; // 重置未保存标志
    } catch (err) {
      console.error('自动保存出错:', err);
    } finally {
      saving = false; // 保存完成
    }
  }

  // 设置定时检测（每隔 5 秒尝试自动保存）
  setInterval(autoSave, 5000);
}

// 保存 BPMN 数据到后端
function saveBpmnToServer(modeler) {
  // 调用 modeler 的 saveXML 方法，导出 XML 数据
  modeler.saveXML({ format: true }) // 设置格式化 XML
      .then(async (result) => {
        const { xml } = result; // 获取导出的 XML 数据
        console.log('导出的 BPMN XML:', xml); // 打印 XML 查看

        // 将 BPMN 数据发送到服务器
        const response = await fetch('http://localhost:1234/save-bpmn', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ bpmnData: xml }) // 将 XML 数据作为 JSON 提交
        });

        if (!response.ok) {
          throw new Error(`保存失败: ${response.status}`);
        }

        const resultData = await response.json();
        console.log('保存成功:', resultData);
      })
      .catch((error) => {
        console.error('导出或保存 BPMN 数据时出错:', error);
      });
}
